// One row per monitored workflow:
//   workflow            e.g. "Daily invoice sync"
//   last_success        ISO timestamp written by that workflow
//   max_age_minutes     how long is too long
//
// Emits one item per STALE workflow. Emits nothing when all are healthy,
// which is exactly what you want — no news is no alert.
const now = Date.now();
const stale = [];

for (const item of $input.all()) {
  const row = item.json;
  const name = row.workflow ?? 'unnamed';
  const maxAge = Number(row.max_age_minutes ?? 60);
  const last = row.last_success ? Date.parse(row.last_success) : NaN;

  // A missing or unparseable timestamp is a failure, not a skip.
  if (!Number.isFinite(last)) {
    stale.push({ json: { workflow: name, ageMinutes: null, maxAge, reason: 'no valid last_success timestamp' } });
    continue;
  }

  const ageMinutes = Math.round((now - last) / 60000);
  if (ageMinutes > maxAge) {
    stale.push({ json: { workflow: name, ageMinutes, maxAge, reason: 'overdue' } });
  }
}

return stale;

// Name the workflow, the age, and the expectation. A vague alert gets ignored.
return $input.all().map((item) => {
  const d = item.json;
  const age = d.ageMinutes === null ? 'never recorded' : `${d.ageMinutes} min ago`;
  return {
    json: {
      alert: `🟠 *${d.workflow}* has not succeeded recently.\nLast success: ${age}\nExpected at least every ${d.maxAge} min\nReason: ${d.reason}`,
    },
  };
});
